        => new(life, s, Signature.Of(Oc(r, m, s, sz)), LoopCount.Of(1));

    // ════════════ 基础：At(t) 瞬时并集（对照手动 Union） ════════════
    [Fact]
    public void At_OverlappingEvents_UnionsFootprints()
    {
